  const bar = add(h, F('Bar', { dir: 'H', main: 'SPACE_BETWEEN', cross: 'CENTER' }), { w: 'fill', h: HEADER_H, maxW: MAXW });
  add(bar, svg(DATA.logo, 'LOGO', 88));
