  if (rest.length) add(h2, T(rest.join('\n'), { key: 'about.heading.1', size: 28.8, weight: 900, lh: 1.2, color: 'inkSoft' }), { w: 'fill' });
  const body = add(text, F('Body', { gap: 18 }), { w: 'fill' });
